export function regionMatrix(region,elapsed,f){const hold=Math.max(.1,f.villageSeamstressHold||3),duration=Math.max(.1,f.gestureDuration||1.685),age=f.gestureTiming==='fit'?Math.max(0,Math.min(1,elapsed/hold))*gestureTrack.duration:Math.max(0,Math.min(1,(elapsed-Math.max(0,hold-duration))/duration))*gestureTrack.duration,A=sampleGesture(age)[region],sp=gestureTrack.sourcePivots[region].map((v,i)=>v*(i?540:960)),p=gestureTrack.artworkPivots[region].map((v,i)=>v*(i?540:960)),prefix='gesture'+region[0].toUpperCase()+region.slice(1),gain=(f[prefix+'Gain']??1)*(f.gestureStrength??1),a=1+(A[0][0]-1)*gain,b=A[1][0]*gain,cc=A[0][1]*gain,d=1+(A[1][1]-1)*gain,dx=(A[0][0]*sp[0]+A[0][1]*sp[1]+A[0][2]-sp[0])*gain,dy=(A[1][0]*sp[0]+A[1][1]*sp[1]+A[1][2]-sp[1])*gain,scale=f[prefix+'Scale']??1,r=(f[prefix+'Rotation']||0)*Math.PI/180,co=Math.cos(r)*scale,si=Math.sin(r)*scale;return [co*a-si*b,si*a+co*b,co*cc-si*d,si*cc+co*d,p[0]+co*dx-si*dy-(co*a-si*b)*p[0]-(co*cc-si*d)*p[1]+(f[prefix+'X']||0),p[1]+si*dx+co*dy-(si*a+co*b)*p[0]-(si*cc+co*d)*p[1]+(f[prefix+'Y']||0)]}
